INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('yuyao', '余姚路店', 'Yuyao Road Store', '余姚路店', '2009年的第一家裕和堂——创始首店，艾香未改。', 'Where Yuhetang began in 2009—the founding store, mugwort scent unchanged.', '2009年創業の第一店—創業店、艾香は変わらず。', '2009年12月，裕和堂的故事从这里开始。余姚路店是品牌创始首店，多年来服务曹家渡一带的街坊。门面不大，进店别有洞天：月洞门、名医挂画、自种艾草陈列。想体验最原味的裕和堂，来创始店。', 'December 2009, the story started here. The founding store serving Caojiadu for years—modest facade, surprising interior: moon gate, physician scrolls, home-grown mugwort. For the most authentic Yuhetang, start here.', '2009年12月、物語はここから。曹家渡の街坊に長年サービス。小さな外観、中は別天地：月洞門、名医掛画、自種艾陳列。最も原味の裕和堂を体験するなら創業店へ。', '地铁14号线武宁路站5A口出站，沿武宁路向东步行约200米至余姚路790号，上2楼即到。曹家渡商圈，建议高峰时段提前预约。', 'Metro Line 14 Wuning Rd, Exit 5A, walk ~200 m east on Wuning Rd to 790 Yuyao Rd, 2F. Caojiadu area—book ahead at peak times.', '地下鉄14号線武寧路駅5A出口、武寧路を東へ約200m、余姚路790号2階。曹家渡、ピーク時は予約推奨。', '静安区余姚路790号2楼', '2F, 790 Yuyao Rd, Jing''an', '静安区余姚路790号2階', '021-33533572', '9:30–23:00', '14号线武宁路站5A口约200m', 'Line 14 Wuning Rd Exit 5A ~200m', '地下鉄14号線武寧路駅5A出口約200m', '/uploads/20251209/c252143430d7eb63ba7f090f3b365153.png', '/uploads/20251209/c252143430d7eb63ba7f090f3b365153.png', '/uploads/20251209/c252143430d7eb63ba7f090f3b365153.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,heritage', 1, 1, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('bailemen', '百乐门店', 'Paramount Store', '百楽門店', '静安寺旁、百乐门里——在老上海地标里做一场中式调理。', 'Beside Jing''an Temple, inside the Paramount—a classic Shanghai wellness stop.', '静安寺そば、百楽門の中で中式調理。', '开在百乐门这一上海人熟悉的地标。2014年开业至今，已是静安寺商圈口碑最厚的养生去处之一：花格漏光吊顶、中药百子柜前台、罗汉榻茶室。27间理疗房，也常接待慕名而来的外国客人。', 'Inside the iconic Paramount since 2014—a trusted wellness address near Jing''an Temple: lattice ceilings, herbal cabinet reception, Luohan tea lounge. 27 rooms; popular with international guests.', '2014年開業、静安寺商圈で信頼の養生スポット。花格天井、百子櫃前台、羅漢榻茶室。27間理療房、外国のお客様も多い。', '地铁2/7号线静安寺站出站，步行约110–210米至南京西路1728号百乐门大都会，乘电梯至11楼。商圈停车紧张，建议地铁或预约后到店。', 'Metro Lines 2/7 Jing''an Temple, walk 110–210 m to 1728 West Nanjing Rd, Paramount Metropolis, 11F. Limited parking—metro or book ahead.', '地下鉄2/7号線静安寺駅、南京西路1728号百楽門大都会11階へ110–210m。駐車困難、地下鉄または予約推奨。', '静安区南京西路1728号百乐门大都会11楼', '11F, Paramount, 1728 Nanjing West Rd, Jing''an', '静安区南京西路1728号百楽門大都会11階', '021-62310862', '9:30–23:00', '静安寺站约110–210m', 'Jing''an Temple Station ~110–210m', '静安寺駅約110–210m', '/uploads/20251209/b71edff2c30709c8fa5649d8e806ee6b.png', '/uploads/20251209/b71edff2c30709c8fa5649d8e806ee6b.png', '/uploads/20251209/b71edff2c30709c8fa5649d8e806ee6b.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,rooms27,lounge', 1, 2, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('huashan', '华山路店', 'Huashan Road Store', '華山路店', '武康路的漫步，收尾在一张理疗床上。', 'End your Wukang Road stroll on a treatment bed.', '武康路の散歩、理療ベッドで締めくくる。', '从武康路的梧桐树影走出来不远即是华山路店。2025年迁址焕新，32间理疗房、配淋浴房，是裕和堂规模最大的门店；逛完安福路、武康路的疲惫可在此彻底卸下。', 'Steps from Wukang Road''s plane trees. Relocated and refreshed in 2025—32 rooms with showers, our largest store. Unwind after Anfu or Wukang Road.', '武康路の梧桐から歩いてすぐ。2025年移転リニューアル、32間＋シャワー、最大店舗。安福路・武康路の後に。', '逛完武康路后沿华山路步行可达。地址：华山路800弄丁香公寓6号裙楼5楼501室。大楼内需按指引乘电梯至5楼，建议提前电话确认入口。', 'Walk from Wukang Road along Huashan Rd. Address: 5F, Building 6, 800 Huashan Rd. Take elevator to 5F per building signs; call ahead to confirm entrance.', '武康路から華山路へ。華山路800弄丁香公寓6号裙楼5階501室。ビル内5階へ、入口は事前電話確認推奨。', '长宁区华山路800弄丁香公寓6号裙楼5楼501室', '501, 5F, Building 6 podium, 800 Huashan Rd, Changning', '長寧区華山路800弄丁香公寓6号裙楼5階501室', '021-62268933', '9:30–23:00', '近武康路', 'Near Wukang Road', '武康路近く', '/uploads/20251209/907aa6f9e5862635c5434f25bc86a79f.png', '/uploads/20251209/907aa6f9e5862635c5434f25bc86a79f.png', '/uploads/20251209/907aa6f9e5862635c5434f25bc86a79f.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,rooms32,shower', 1, 3, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('taiguhui', '太古汇店', 'Taikoo Hui Store', '太古匯店', '南京西路上空29层——闹市顶上的一方静境。', '29 floors above West Nanjing Road—quiet above the bustle.', '南京西路29階—喧騒の上の静境。', '在南京西路商圈第29层，把喧嚣关在电梯之外。2018年开业，红木与灰砖、罗汉榻与黑石前台，是裕和堂「闹中取静」的代表门店，也适合商务接待。', 'On the 29th floor, hustle stays outside the elevator. Since 2018—rosewood and grey brick, Luohan daybeds, black stone reception. Our "quiet in the city" flagship, great for business guests.', '2018年開業、29階で喧騒をエレベーターの外に。紅木と灰磚、羅漢榻、黒石前台。闹中取静の代表、ビジネス接待にも。', '地铁2/12/13号线南京西路站或兴业太古汇步行约200米，至青海路118号云海苑，乘电梯至29楼。适合南京西路逛街后顺路调理。', 'Metro Lines 2/12/13 West Nanjing Rd or ~200 m from Taikoo Hui to 118 Qinghai Rd, Yunhai Yuan, 29F. Ideal after shopping on West Nanjing Rd.', '地下鉄2/12/13号線南京西路駅または太古匯から約200m、青海路118号雲海苑29階。南京西路ショッピング後に。', '静安区青海路118号云海苑29楼', '29F, 118 Qinghai Rd, Jing''an', '静安区青海路118号雲海苑29階', '021-52799673', '9:00–23:00', '兴业太古汇、南京西路站约200m', 'HKRI Taikoo Hui / Nanjing West Rd ~200m', '太古匯・南京西路駅約200m', '/uploads/20251209/734afdcb6e76f1e01f0044519109a207.png', '/uploads/20251209/734afdcb6e76f1e01f0044519109a207.png', '/uploads/20251209/734afdcb6e76f1e01f0044519109a207.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,highFloor,business', 1, 4, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('wujianglu', '吴江路店', 'Wujiang Road Store', '呉江路店', '地铁口90米——上班族的午间「回血站」。', '90 m from the metro—the lunch-break recharge station.', '地下鉄口90m—昼休みの「回血ステーション」。', '南京西路站14口出来90米即到，大概是裕和堂最方便的一家。蓝墙金标、月洞门走廊，小而精致。工作日午间11:30–13:30最热闹——午休做一节60分钟推拿，下午照样精神。午间高峰建议提前预约。', 'Exit 14 of West Nanjing Rd station, 90 m away—our most convenient store. Blue walls, moon-gate corridor, compact and refined. Weekday lunch 11:30–13:30 is busiest—a 60-minute massage and back to work refreshed.', '南京西路駅14出口から90m、最も便利。青壁金標、月洞門廊。平日11:30–13:30がピーク、60分推拿で午後も元気。', '地铁2/12/13号线南京西路站14号口出站，步行约90米至南京西路993号锦江向阳大楼18楼A室。午间高峰建议提前邮箱或电话预约。', 'Metro Lines 2/12/13 West Nanjing Rd, Exit 14, ~90 m to 993 West Nanjing Rd, Jinjiang Xiangyang Building, 18F-A. Book by email or phone at lunch peak.', '地下鉄2/12/13号線南京西路駅14出口、約90m、南京西路993号錦江向陽大楼18階A室。昼ピークはメール・電話予約推奨。', '静安区南京西路993号锦江向阳大楼18楼A室', '18F-A, 993 Nanjing West Rd, Jing''an', '静安区南京西路993号錦江向陽大楼18階A室', '18521945341', '9:30–23:00', '南京西路站14口约90m', 'Nanjing West Rd Exit 14 ~90m', '南京西路駅14出口約90m', '/uploads/20251209/b40ecb20c99c01358b9bcfdb937d0264.png', '/uploads/20251209/b40ecb20c99c01358b9bcfdb937d0264.png', '/uploads/20251209/b40ecb20c99c01358b9bcfdb937d0264.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,metroNear,lunchPeak', 1, 5, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('shanghai-center', '上海中心店', 'Shanghai Tower Store', '上海中心店', '把「散架」的自己，在上海之巅拼回来。', 'Put yourself back together at the top of Shanghai.', '上海の頂で、バラバラの自分を戻す。', '2022年入驻上海中心大厦，在中国第一高楼里开一家中医养生馆。空间以「人在水间行走」为意象：水景、水墨屏风、原木理疗间，并配智能净烟艾灸设备。2026年完成扩店，28间理疗房。', 'Since 2022 inside Shanghai Tower—TCM wellness in China''s tallest building. "Walking on water" design: water features, ink screens, wood rooms, smart smoke-control moxibustion. Expanded in 2026 to 28 rooms.', '2022年上海中心大厦出店。水景、水墨屏風、原木理療室、智能浄煙艾灸。2026年拡店、28間理療房。', '地铁2号线陆家嘴站出站步行约270米，至花园石桥路158号上海中心大厦，下至B1层7室。可从陆家嘴商圈步行直达，建议提前预约。', 'Metro Line 2 Lujiazui, ~270 m to 158 Huayuanshiqiao Rd, Shanghai Tower, B1-7. Walkable from Lujiazui—booking recommended.', '地下鉄2号線陸家嘴駅約270m、花園石橋路158号上海中心大厦B1層7室。陸家嘴から徒歩可、予約推奨。', '浦东新区花园石桥路158号上海中心大厦B1层7室', 'B1-7, Shanghai Tower, 158 Huayuanshiqiao Rd, Pudong', '浦東新区花園石橋路158号上海中心大厦B1層7室', '021-50181919', '9:00–23:00', '陆家嘴站约270m', 'Lujiazui Station ~270m', '陸家嘴駅約270m', '/uploads/20251209/8df4c3037b4bfd6444ecf8df8b071a10.png', '/uploads/20251209/8df4c3037b4bfd6444ecf8df8b071a10.png', '/uploads/20251209/8df4c3037b4bfd6444ecf8df8b071a10.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,rooms28,smartMoxa', 1, 6, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('meihua', '梅花路店', 'Meihua Road Store', '梅花路店', '9家店里唯一的中医诊所——有医生坐诊，可用商保。', 'Our only TCM clinic—with physicians and commercial insurance.', '9店唯一の中医診所—医師坐诊、商保利用可。', '梅花路店是裕和堂旗下的持证中医诊所：有坐诊医生、支持商业保险（9店中唯一）、提供专业小儿推拿。店面临近世纪公园与上海新国际博览中心，服务周边家庭。', 'Licensed TCM clinic: on-site physicians, commercial insurance (only among 9 stores), professional pediatric tuina. Near Century Park and SNIEC, serving families and expo visitors.', '中医診療所：坐诊医師、商業保険（9店唯一）、専門小児推拿。世紀公園・新国博近く、ファミリー・会展客に。', '地铁7号线花木路站4口出站步行约200米至梅花路1019号。近世纪公园与新国际博览中心，家庭客与会展访客较多，小儿推拿建议提前预约。', 'Metro Line 7 Huamu Rd, Exit 4, ~200 m to 1019 Meihua Rd. Near Century Park and SNIEC—book pediatric tuina ahead.', '地下鉄7号線花木路駅4出口約200m、梅花路1019号。小児推拿は予約推奨。', '浦东新区梅花路1019号', '1019 Meihua Rd, Pudong', '浦東新区梅花路1019号', '021-58560050', '9:00–23:00', '7号线花木路站4口约200m', 'Line 7 Huamu Rd Exit 4 ~200m', '地下鉄7号線花木路駅4出口約200m', '/uploads/20251209/6e29f74810a66f1c3d49936a36b89b51.png', '/uploads/20251209/6e29f74810a66f1c3d49936a36b89b51.png', '/uploads/20251209/6e29f74810a66f1c3d49936a36b89b51.png', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,clinic,insurance,pediatric', 1, 7, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('sichuanbei', '四川北路店', 'North Sichuan Road Store', '四川北路店', '北外滩的新据点——虹口人的裕和堂来了。', 'North Bund outpost—Yuhetang comes to Hongkou.', '北外灘の新拠点—虹口に裕和堂。', '2026年，裕和堂落地北外滩，把多年的直营标准带进虹口。空间明亮干净，14间理疗房；客人以周边白领、居民及沿四川北路逛到北外滩的游客为主。', 'Opened 2026 on the North Bund—14 bright treatment rooms; guests from nearby offices, residents and North Bund visitors.', '2026年北外灘出店、14間理療房。周辺オフィス・住民・北外灘観光客。', '地铁10号线四川北路站3口出站步行约390米至四川北路888号3楼303室。沿四川北路向北外滩方向步行可达，建议提前预约。', 'Metro Line 10 North Sichuan Rd, Exit 3, ~390 m to 888 North Sichuan Rd, 3F-303. Walk north along North Sichuan Rd toward North Bund—booking recommended.', '地下鉄10号線四川北路駅3出口約390m、四川北路888号3階303室。予約推奨。', '虹口区四川北路888号303室', '303, 888 Sichuan North Rd, Hongkou', '虹口区四川北路888号303室', '18917108817', '9:00–23:00', '10号线四川北路站3口约390m', 'Line 10 Sichuan North Rd Exit 3 ~390m', '地下鉄10号線四川北路駅3出口約390m', '/uploads/20251209/ae4511188539e35b05e048ba8017be04.jpg', '/uploads/20251209/434a36f45c2c6d7a5e24247088deda18.jpg', '/uploads/20251209/9f67ee25bd99d959a575cd45d9aca506.jpg', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,rooms14', 1, 8, UNIX_TIMESTAMP());
INSERT INTO `fa_ygame_store` (`slug`, `title`, `title_en`, `title_jp`, `tagline`, `tagline_en`, `tagline_jp`, `intro`, `intro_en`, `intro_jp`, `directions`, `directions_en`, `directions_jp`, `address`, `address_en`, `address_jp`, `phone`, `hours`, `metro`, `metro_en`, `metro_jp`, `image`, `image_en`, `image_jp`, `services`, `facilities`, `status`, `weigh`, `createtime`) VALUES
('changde', '常德路店', 'Changde Road Store', '常徳路店', '东方禅意的静养空间——新店，老手艺。', 'Zen quiet space—new store, timeless craft.', '東方禅意の静養空間—新店、老い手艺。', '2026年开业，是9家店里最「静」的一家：深色木饰面、微水泥墙面、枯山水造景。服务同乐坊、江宁路一带社区，18间理疗房，没有商圈店的匆忙。', 'Opened 2026—our quietest store: dark wood, micro-cement walls, dry landscape. Serves Tonglefang and Jiangning Rd community, 18 rooms, unhurried unlike mall locations.', '2026年開業、最も「静」な店。ダークウッド、微水泥、枯山水。同楽坊・江寧路コミュニティ、18間、商圈店の慌ただしさなし。', '地铁7号线昌平路站5口出站步行约340米至常德路1010号2层。近同乐坊、江宁路社区，环境安静，适合周末慢调理。', 'Metro Line 7 Changping Rd, Exit 5, ~340 m to 1010 Changde Rd, 2F. Near Tonglefang and Jiangning Rd—ideal for slow weekend care.', '地下鉄7号線昌平路駅5出口約340m、常徳路1010号2階。週末のゆっくり調理に。', '静安区常德路1010号2层', '2F, 1010 Changde Rd, Jing''an', '静安区常徳路1010号2階', '021-62078806', '9:30–23:00', '昌平路站5口约340m', 'Changping Rd Exit 5 ~340m', '昌平路駅5出口約340m', '/uploads/20251209/cb710396e6a751be57336c79cf692915.jpg', '/uploads/20251209/bfdf2cec8b897522d945c80215dc2f0f.jpg', '/uploads/20251209/a95293cf372117e949c83383b88ef997.jpg', 'moxibustion,tuina,spa,foot,traditional', 'privateRoom,tea,hygienic,rooms18,zen', 1, 9, UNIX_TIMESTAMP());
